import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
// Min reduction over the middle dimension of a contiguous 3D-like layout.
// Input viewed as [outer, R, inner]; output is [outer, inner].
// out[b, n] = min over r of in[b*R*inner + r*inner + n]
// Optimization: intra-CTA three-way split-R for full-wave balance.
// Thread triples share one 4-column group and reduce three nearly
// equal R ranges ([0,ceil(R/3)), [ceil(R/3),2*ceil(R/3)), and
// [2*ceil(R/3),R)). With 384 threads (128 groups) per CTA, four
// CTAs exactly fill an SM and a 512-CTA launch is one full wave;
// each CTA processes two uniform work items for the target shape.
// The second and third threads stage their partial minima through
// shared memory between two barriers, and the first thread merges
    // Each thread still reduces 4 consecutive inner columns (4 independent
    // accumulators) and uses ld.global.v4.f32 whenever the row pointer is
    // 16-byte aligned, with a predicated 4x scalar fallback otherwise.
    // The row loop is unrolled by two rather than four and keeps only one
    // temporary row pointer live. This lowers register pressure enough for
    // four resident CTAs/SM; the grid-stride persistent launch is kept.
.visible .entry min_reduce_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 outer,
    .param .u32 R,
    .param .u32 inner
)
{
    .reg .pred %p<16>;
    .reg .b32 %r<40>;
    .reg .b64 %rd<20>;
    .reg .f32 %f<24>;
    // per-CTA staging buffer: up to 256 column groups * 32 bytes
    // (two staged 16-byte vectors per group)
    .shared .align 16 .b8 s_part[8192];
    // load kernel parameters once (invariant across work items)
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r7, [outer];
    ld.param.u32 %r8, [R];
    ld.param.u32 %r6, [inner];
    mov.u32 %r2, %ntid.x;             // blockDim.x
    mov.u32 %r4, %tid.x;
    div.u32 %r33, %r2, 3;             // groups per block = blockDim.x/3
    div.u32 %r32, %r4, %r33;          // third = contiguous thread section
    rem.u32 %r31, %r4, %r33;          // group = lane within section
    shl.b32 %r3, %r33, 2;             // columns per block = groups*4
    // tiles_x = ceil(inner / columns_per_block)
    add.u32 %r17, %r6, %r3;
    sub.u32 %r17, %r17, 1;
    div.u32 %r18, %r17, %r3;          // tiles_x
    // Balanced tiling: split the ceil(inner/4) column groups as evenly
    // as possible across tiles (tile group counts differ by at most
    // one), so every work item has nearly identical reduction work.
    // The previous fixed groups_per_block-sized tiles left the last
    // tile ~5x lighter with inner=4095, causing the SM active-cycle
    // imbalance flagged by the profiler. T is loop-invariant.
    add.u32 %r37, %r6, 3;
    shr.u32 %r37, %r37, 2;            // G = ceil(inner/4)
    add.u32 %r37, %r37, %r18;
    sub.u32 %r37, %r37, 1;
    div.u32 %r39, %r37, %r18;         // T = ceil(G / tiles_x) groups per tile
    mul.lo.u32 %r19, %r7, %r18;       // total work items = outer * tiles_x
    // w = ctaid.y * nctaid.x + ctaid.x ; step = nctaid.x * nctaid.y
    mov.u32 %r20, %nctaid.x;
    mov.u32 %r21, %nctaid.y;
    mul.lo.u32 %r22, %r20, %r21;      // grid-stride step
    mov.u32 %r23, %ctaid.y;
    mul.lo.u32 %r24, %r23, %r20;
    mov.u32 %r1, %ctaid.x;
    add.u32 %r24, %r24, %r1;          // w = first work item for this CTA
    // R split point: chunk = ceil(R/3); this thread covers [r_begin,r_end)
    add.u32 %r34, %r8, 2;
    div.u32 %r34, %r34, 3;            // chunk
    mul.lo.u32 %r35, %r32, %r34;      // r_begin = third*chunk
    add.u32 %r36, %r35, %r34;
    min.u32 %r36, %r36, %r8;          // r_end = min(r_begin+chunk, R)
    sub.u32 %r38, %r36, %r35;         // row count for this third
    // row stride in bytes = inner*4 (loop-invariant); keep no multi-row advance registers live
    mul.wide.u32 %rd5, %r6, 4;
WORK_LOOP:
    setp.ge.u32 %p1, %r24, %r19;
    @%p1 bra DONE;                    // no work items left
    // b = w / tiles_x ; tile = w % tiles_x ; n0 = (tile*groups+group)*4
    div.u32 %r9, %r24, %r18;          // b
    rem.u32 %r25, %r24, %r18;         // tile
    mul.lo.u32 %r26, %r25, %r39;          // tile * T (balanced groups per tile)
    add.u32 %r26, %r26, %r31;         // thread column-group index
    shl.b32 %r5, %r26, 2;             // n0 = first column of this group
    setp.lt.u32 %p2, %r5, %r6;        // group has at least 1 valid lane
    // p3 = full 4-column group (n0+4 <= inner)
    add.u32 %r27, %r5, 4;
    setp.le.u32 %p3, %r27, %r6;
    // per-lane valid predicates for ragged groups and stores
    add.u32 %r28, %r5, 1;
    setp.lt.u32 %p4, %r28, %r6;       // lane 1 valid
    add.u32 %r29, %r5, 2;
    setp.lt.u32 %p5, %r29, %r6;       // lane 2 valid
    add.u32 %r30, %r5, 3;
    setp.lt.u32 %p6, %r30, %r6;       // lane 3 valid
    // four independent accumulators (one per column) = +inf
    mov.f32 %f1, 0f7F800000;
    mov.f32 %f2, 0f7F800000;
    mov.f32 %f3, 0f7F800000;
    mov.f32 %f4, 0f7F800000;
    @!%p2 bra COMBINE;                // out-of-range group: barriers only
    // base element offset = (b*R + r_begin)*inner + n0
    mul.lo.u32 %r10, %r9, %r8;
    add.u32 %r10, %r10, %r35;
    mul.lo.u32 %r11, %r10, %r6;
    add.u32 %r12, %r11, %r5;
    // running pointer = in_ptr + base*4; the second row is formed in the loop
    mul.wide.u32 %rd3, %r12, 4;
    add.u64 %rd4, %rd1, %rd3;         // p0
    @!%p3 bra PARTIAL_THREAD;         // ragged group: scalar path
    @!%p3 bra PARTIAL_THREAD;         // ragged group: scalar path
    // Two-row unrolling keeps only one temporary row pointer and half as
    // many load registers live, lowering occupancy-limiting register pressure.
    mov.u32 %r13, 0;                  // r = 0 (within this third)
    and.b32 %r14, %r38, 0xFFFFFFFE;   // count rounded down to a multiple of 2
UNROLL_LOOP:
    setp.lt.u32 %p7, %r13, %r14;
    @!%p7 bra REM_LOOP;
    // Form only the second row pointer and compute both row alignments.
    add.u64 %rd11, %rd4, %rd5;
    and.b64 %rd14, %rd4, 15;
    setp.eq.u64 %p8, %rd14, 0;
    and.b64 %rd14, %rd11, 15;
    setp.eq.u64 %p9, %rd14, 0;
    // Issue both row loads (vector when aligned) before consuming them.
    @!%p8 ld.global.f32 %f5, [%rd4];
    @!%p8 ld.global.f32 %f6, [%rd4+4];
    @!%p8 ld.global.f32 %f7, [%rd4+8];
    @!%p8 ld.global.f32 %f8, [%rd4+12];
    @%p8 ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%rd4];
    @!%p9 ld.global.f32 %f9, [%rd11];
    @!%p9 ld.global.f32 %f10, [%rd11+4];
    @!%p9 ld.global.f32 %f11, [%rd11+8];
    @!%p9 ld.global.f32 %f12, [%rd11+12];
    @%p9 ld.global.v4.f32 {%f9, %f10, %f11, %f12}, [%rd11];
    // Advance by two rows without keeping a separate advance register.
    add.u64 %rd4, %rd4, %rd5;
    add.u64 %rd4, %rd4, %rd5;
    // Consume eight independent values after both rows are in flight.
    min.f32 %f1, %f1, %f5;
    min.f32 %f2, %f2, %f6;
    min.f32 %f3, %f3, %f7;
    min.f32 %f4, %f4, %f8;
    min.f32 %f1, %f1, %f9;
    min.f32 %f2, %f2, %f10;
    min.f32 %f3, %f3, %f11;
    min.f32 %f4, %f4, %f12;
    add.u32 %r13, %r13, 2;
    bra UNROLL_LOOP;
REM_LOOP:
    setp.ge.u32 %p7, %r13, %r38;
    @%p7 bra COMBINE;
    and.b64 %rd14, %rd4, 15;
    setp.eq.u64 %p12, %rd14, 0;
    @!%p12 ld.global.f32 %f5, [%rd4];
    @!%p12 ld.global.f32 %f6, [%rd4+4];
    @!%p12 ld.global.f32 %f7, [%rd4+8];
    @!%p12 ld.global.f32 %f8, [%rd4+12];
    @%p12 ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%rd4];
    min.f32 %f1, %f1, %f5;
    min.f32 %f2, %f2, %f6;
    min.f32 %f3, %f3, %f7;
    min.f32 %f4, %f4, %f8;
    add.u64 %rd4, %rd4, %rd5;
    add.u32 %r13, %r13, 1;
    bra REM_LOOP;
PARTIAL_THREAD:
    // ragged 4-column group (n0 < inner < n0+4): per-lane predicated loads
    mov.u32 %r13, 0;                  // r = 0 (within this half)
PARTIAL_LOOP:
    setp.ge.u32 %p7, %r13, %r38;
    @%p7 bra COMBINE;
    mov.f32 %f5, 0f7F800000;
    mov.f32 %f6, 0f7F800000;
    mov.f32 %f7, 0f7F800000;
    mov.f32 %f8, 0f7F800000;
    ld.global.f32 %f5, [%rd4];        // lane 0 always valid (n0 < inner)
    @%p4 ld.global.f32 %f6, [%rd4+4];
    @%p5 ld.global.f32 %f7, [%rd4+8];
    @%p6 ld.global.f32 %f8, [%rd4+12];
    min.f32 %f1, %f1, %f5;
    min.f32 %f2, %f2, %f6;
    min.f32 %f3, %f3, %f7;
    min.f32 %f4, %f4, %f8;
    add.u64 %rd4, %rd4, %rd5;
    add.u32 %r13, %r13, 1;
    bra PARTIAL_LOOP;
COMBINE:
    // Merge the three R-third partial minima; all threads hit both barriers.
    bar.sync 0;
    mov.u64 %rd15, s_part;
    mul.wide.u32 %rd16, %r31, 32;
    add.u64 %rd15, %rd15, %rd16;
    setp.eq.u32 %p13, %r32, 1;
    @%p13 st.shared.v4.f32 [%rd15], {%f1, %f2, %f3, %f4};
    setp.eq.u32 %p14, %r32, 2;
    @%p14 st.shared.v4.f32 [%rd15+16], {%f1, %f2, %f3, %f4};
    bar.sync 0;
    setp.ne.u32 %p13, %r32, 0;
    @%p13 bra NEXT_WORK;
    ld.shared.v4.f32 {%f5, %f6, %f7, %f8}, [%rd15];
    ld.shared.v4.f32 {%f9, %f10, %f11, %f12}, [%rd15+16];
    min.f32 %f1, %f1, %f5;
    min.f32 %f2, %f2, %f6;
    min.f32 %f3, %f3, %f7;
    min.f32 %f4, %f4, %f8;
    min.f32 %f1, %f1, %f9;
    min.f32 %f2, %f2, %f10;
    min.f32 %f3, %f3, %f11;
    min.f32 %f4, %f4, %f12;
    @!%p2 bra NEXT_WORK;              // out-of-range group: no store
    // out[b*inner + n0 + lane] = accumulator lane (predicated if ragged)
    mul.lo.u32 %r15, %r9, %r6;
    add.u32 %r16, %r15, %r5;
    mul.wide.u32 %rd6, %r16, 4;
    add.u64 %rd7, %rd2, %rd6;
    st.global.f32 [%rd7], %f1;
    @%p4 st.global.f32 [%rd7+4], %f2;
    @%p5 st.global.f32 [%rd7+8], %f3;
    @%p6 st.global.f32 [%rd7+12], %f4;
NEXT_WORK:
    add.u32 %r24, %r24, %r22;         // w += step
    bra WORK_LOOP;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
_device_props_cache = {}
def _get_device_props(device):
    dev_index = device.index
    if dev_index is None:
        dev_index = torch.cuda.current_device()
    props = _device_props_cache.get(dev_index)
    if props is None:
        props = torch.cuda.get_device_properties(dev_index)
        _device_props_cache[dev_index] = props
    return props

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("min_reduce_kernel")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        """
        Initializes the model with the dimension to reduce over.

        Args:
            dim (int): The dimension to reduce over.
        """
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()

        ndim = x.dim()
        dim = self.dim
        if dim < 0:
            dim += ndim

        shape = x.shape
        outer = 1
        for i in range(dim):
            outer *= shape[i]
        R = shape[dim]
        inner = 1
        for i in range(dim + 1, ndim):
            inner *= shape[i]

        out_shape = list(shape[:dim]) + list(shape[dim + 1:])
        out = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        # 384 threads/block: 4 resident CTAs per SM (1536 threads/SM, 100%
        # theoretical occupancy). With 128 column groups per block, the
        # kernel-side balanced tiling gives tiles_x=8 for inner=4095;
        # outer*tiles_x=1024 uniform work items. A 512-CTA launch is
        # exactly one resident wave and each CTA receives exactly two
        # work items, eliminating the profiler-flagged 128-block partial
        # wave while keeping every SM fully populated.
        block_x = 384
        # Thread triples split the R range in thirds for one shared
        # 4-column group (intra-CTA split-R merged via shared memory)
        # while each thread still uses 128-bit ld.global.v4.f32 loads
        # with a predicated scalar fallback, so one block covers
        # (block_x // 3) * 4 columns of the inner dim.
        items_per_block = (block_x // 3) * 4
        grid_x = (inner + items_per_block - 1) // items_per_block
        total_items = outer * grid_x
        # Persistent-style launch: cap the grid at one full resident wave.
        # The kernel grid-strides over the (outer, n-tile) work items, so
        # no partial-wave tail is created when extra work remains.
        props = _get_device_props(x.device)
        blocks_per_sm = max(1, props.max_threads_per_multi_processor // block_x)
        wave_blocks = props.multi_processor_count * blocks_per_sm
        num_blocks = min(total_items, wave_blocks)
        module.launch(
            "min_reduce_kernel",
            grid=(num_blocks, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, u32(outer), u32(R), u32(inner)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

